INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Wird Multicast nur für Gerätesuche genutzt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Streaming und mehr"}, {"text": "Ja", "correct": false, "because": "Nutzung ist breiter"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt Multicast bei NDP?', 3, '[{"text": "Nachbarschaftserkennung", "correct": true, "because": "Solicitation an Gruppe"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Nicht Multicast-Aufgabe"}, {"text": "Routing-Optimierung", "correct": false, "because": "Router-Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anwendungen nutzen Multicast?', 5, '[{"text": "Neighbor Discovery", "correct": true, "because": "Findet Geräte via NDP"}, {"text": "Gerätesuche", "correct": true, "because": "z. B. mDNS"}, {"text": "Einzelverbindungen", "correct": false, "because": "Unicast-Aufgabe"}, {"text": "Paketkompression", "correct": false, "because": "Nicht Multicast"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Multicast hilft bei NDP. b) Es ersetzt Unicast.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Unicast bleibt eigenständig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Multicast-Nutzung?', 4, '[{"text": "Gruppenadressen", "correct": false, "because": "Kern von Multicast"}, {"text": "Scope", "correct": false, "because": "Definiert Reichweite"}, {"text": "Einzel-IPs", "correct": true, "because": "Multicast ist gruppenbasiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Multicast bei NDP optional ist?', 2, '[{"text": "Nein", "correct": true, "because": "Kernmechanismus von NDP"}, {"text": "Ja", "correct": false, "because": "Pflicht für Solicitation"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse nutze ich für die Gerätesuche?', 3, '[{"text": "FF02::1", "correct": true, "because": "Alle Knoten im Segment"}, {"text": "FE80::1", "correct": false, "because": "Unicast-Adresse"}, {"text": "2001:db8::1", "correct": false, "because": "Globale Unicast"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Multicast bei der Gerätesuche?', 5, '[{"text": "Effiziente Erkennung", "correct": true, "because": "Anfrage an Gruppe"}, {"text": "Ressourcenschonung", "correct": true, "because": "Weniger Pakete"}, {"text": "Hohe Sicherheit", "correct": false, "because": "Keine Verschlüsselung"}, {"text": "Geringe Latenz", "correct": false, "because": "Netzwerkabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Multicast ist bei NDP essenziell. b) Es ist nur für große Netze. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch kleine Netze nutzen es"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Multicast bei NDP?', 4, '[{"text": "Solicited-Node-Adresse", "correct": false, "because": "Für gezielte Abfragen"}, {"text": "FF02::1", "correct": false, "because": "Alle Knoten erreichen"}, {"text": "TCP-Verbindung", "correct": true, "because": "ICMPv6 genügt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Nutzt Multicast bei NDP Unicast-Adressen?', 2, '[{"text": "Nein", "correct": true, "because": "Gruppenadressen sind zentral"}, {"text": "Ja", "correct": false, "because": "Multicast-basiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachricht hilft mir, Geräte im Netz zu finden?', 4, '[{"text": "Neighbor Solicitation", "correct": true, "because": "Multicast an Gruppe"}, {"text": "Echo Request", "correct": false, "because": "Unicast-Diagnose"}, {"text": "Router Advertisement", "correct": false, "because": "Router-Info"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Multicast bei der Gerätesuche ineffizient ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Effizient für Gruppen"}, {"text": "Ja", "correct": false, "because": "Reduziert Paketflut"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Multicast-Nutzung?', 3, '[{"text": "Richtige Gruppenadresse", "correct": true, "because": "Erreicht Zielgeräte"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Netzwerkabhängig"}, {"text": "Schnelle Antwort", "correct": false, "because": "Diagnoseabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) NDP nutzt Multicast für Solicitation. b) Gerätesuche braucht immer DHCP.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "DHCP ist optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen Multicast für NDP nützlich?', 5, '[{"text": "Gruppenabfrage", "correct": true, "because": "Effiziente Erkennung"}, {"text": "Link-Local-Scope", "correct": true, "because": "Lokale Reichweite"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Nicht enthalten"}, {"text": "Hohe Geschwindigkeit", "correct": false, "because": "Netzwerkabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Multicast-Nutzung unwichtig?', 3, '[{"text": "Gruppenadresse", "correct": false, "because": "Definiert Empfänger"}, {"text": "ICMPv6", "correct": false, "because": "Protokollbasis"}, {"text": "Portnummern", "correct": true, "because": "Transportebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ersetzt Multicast bei NDP Unicast komplett?', 3, '[{"text": "Nein", "correct": true, "because": "Unicast für Antworten"}, {"text": "Ja", "correct": false, "because": "Kombination beider"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Multicast bei der Gerätesuche Router überschreitet?', 2, '[{"text": "Nein", "correct": true, "because": "Link-Local begrenzt"}, {"text": "Ja", "correct": false, "because": "Scope-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse wähle ich für gezielte NDP-Abfragen?', 4, '[{"text": "FF02::1:FFXX:XXXX", "correct": true, "because": "Solicited-Node Multicast"}, {"text": "FF02::1", "correct": false, "because": "Alle Knoten"}, {"text": "FE80::1", "correct": false, "because": "Unicast"}]');
